/** 
 * Send an IRC message.
 * @param chatroom The chat room to send the message to.
 * @param message The message to send.
 */
public void message(final ChatRoomIrcImpl chatroom,final String message){
  if (!this.connectionState.isConnected()) {
    throw new IllegalStateException("Not connected to an IRC server.");
  }
  final String target=chatroom.getIdentifier();
  final int maxMsgSize;
  try {
    maxMsgSize = calculateMaximumMessageSize(0,target);
  } catch (IllegalFormatException e) {
    LOGGER.error("Failed to calculate maximum message size due to illegal format: " + e.getMessage(), e);
    return;
  }
  if (maxMsgSize < message.length()) {
    LOGGER.warn("Message for " + target + " is too large. At best only sent message up to: "+ message.substring(0,maxMsgSize));
  }
  this.irc.message(target,message);
}
